=== CustomerFormDrawer.tsx ===
     1	import { useState } from "react";
     2	import {
     3	  Alert,
     4	  Button,
     5	  Description,
     6	  Drawer,
     7	  FieldError,
     8	  Form,
     9	  Input,
    10	  Label,
    11	  ListBox,
    12	  Select,
    13	  TextField,
    14	} from "@heroui/react";
    15	import {
    16	  CUSTOMER_STATUSES,
    17	  hasFormError,
    18	  isCustomerStatus,
    19	  validateCustomerForm,
    20	  type CustomerFormErrors,
    21	  type CustomerFormValues,
    22	} from "./customerModel";
    23	
    24	type CustomerFormDrawerProps = {
    25	  /** Drawer を開くトリガーのラベル(「顧客を追加」/「顧客を編集」) */
    26	  triggerLabel: string;
    27	  triggerVariantClass: string;
    28	  heading: string;
    29	  description: string;
    30	  initialValues: CustomerFormValues;
    31	  /** URL の state から復元する初期エラー(invalid-email 用) */
    32	  initialErrors?: CustomerFormErrors;
    33	  initialFailureReason?: string;
    34	  isOpen: boolean;
    35	  onOpenChange: (isOpen: boolean) => void;
    36	  isSaving: boolean;
    37	  failureReason: string;
    38	  onSubmit: (values: CustomerFormValues) => void;
    39	};
    40	
    41	export function CustomerFormDrawer({
    42	  triggerLabel,
    43	  triggerVariantClass,
    44	  heading,
    45	  description,
    46	  initialValues,
    47	  initialErrors,
    48	  isOpen,
    49	  onOpenChange,
    50	  isSaving,
    51	  failureReason,
    52	  onSubmit,
    53	}: CustomerFormDrawerProps) {
    54	  const [values, setValues] = useState<CustomerFormValues>(initialValues);
    55	  const [errors, setErrors] = useState<CustomerFormErrors>(initialErrors ?? {});
    56	
    57	  function handleOpenChange(nextOpen: boolean) {
    58	    // 保存中は二重送信と誤操作による閉じ込みを防ぐ
    59	    if (isSaving) return;
    60	    if (nextOpen) {
    61	      setValues(initialValues);
    62	      setErrors(initialErrors ?? {});
    63	    }
    64	    onOpenChange(nextOpen);
    65	  }
    66	
    67	  function updateValue<Key extends keyof CustomerFormValues>(key: Key, value: CustomerFormValues[Key]) {
    68	    setValues((current) => ({ ...current, [key]: value }));
    69	    setErrors((current) => ({ ...current, [key]: undefined }));
    70	  }
    71	
    72	  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    73	    event.preventDefault();
    74	    if (isSaving) return;
    75	    const nextErrors = validateCustomerForm(values);
    76	    setErrors(nextErrors);
    77	    if (hasFormError(nextErrors)) return;
    78	    onSubmit({
    79	      companyName: values.companyName.trim(),
    80	      contactName: values.contactName.trim(),
    81	      email: values.email.trim(),
    82	      status: values.status,
    83	    });
    84	  }
    85	
    86	  return (
