     1	import type { CustomerStatus } from "./fixtures";
     2	
     3	export const CUSTOMER_STATUSES: CustomerStatus[] = ["商談中", "利用中", "休眠"];
     4	
     5	/** 追加と編集で共通の入力値。business.customer-name / business.contact-email の対象 */
     6	export type CustomerFormValues = {
     7	  companyName: string;
     8	  contactName: string;
     9	  email: string;
    10	  status: CustomerStatus;
    11	};
    12	
    13	export type CustomerFormErrors = Partial<Record<keyof CustomerFormValues, string>>;
    14	
    15	export const COMPANY_NAME_ERROR = "会社名を入力してください。";
    16	export const EMAIL_FORMAT_ERROR = "メールアドレスは name@example.com の形式で入力してください。";
    17	export const CREATE_FAILURE_REASON = "顧客の追加に失敗しました。時間をおいて再試行してください。";
    18	export const SAVE_FAILURE_REASON = "顧客の保存に失敗しました。時間をおいて再試行してください。";
    19	export const SAVE_SUCCESS_MESSAGE = "顧客を保存しました";
    20	export const DELETE_SUCCESS_MESSAGE = "顧客を削除しました";
    21	
    22	const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    23	
    24	export function isCustomerStatus(value: unknown): value is CustomerStatus {
    25	  return CUSTOMER_STATUSES.some((status) => status === value);
    26	}
    27	
    28	export function validateCustomerForm(values: CustomerFormValues): CustomerFormErrors {
    29	  const errors: CustomerFormErrors = {};
    30	  if (values.companyName.trim().length === 0) errors.companyName = COMPANY_NAME_ERROR;
    31	  if (!emailPattern.test(values.email.trim())) errors.email = EMAIL_FORMAT_ERROR;
    32	  return errors;
    33	}
    34	
    35	export function hasFormError(errors: CustomerFormErrors): boolean {
    36	  return Object.values(errors).some((message) => Boolean(message));
    37	}
    38	
    39	export function statusColor(status: CustomerStatus): "accent" | "success" | "default" {
    40	  if (status === "利用中") return "success";
    41	  if (status === "商談中") return "accent";
    42	  return "default";
    43	}
    44	
    45	export function formatContactDate(value: string): string {
    46	  const [year, month, day] = value.split("-");
    47	  if (!year || !month || !day) return value;
    48	  return `${year}/${month}/${day}`;
    49	}

