    68	      if (!result.ok) {
    69	        setDeleteFailureReason(result.reason);
    70	        return;
    71	      }
    72	      setIsDeleteOpen(false);
    73	      toast.success(DELETE_SUCCESS_MESSAGE, { description: `${customer.companyName}を一覧から削除しました。` });
    74	      void navigate("/customers");
    75	    }, 200);
    76	  }
    77	
    78	  const editValues: CustomerFormValues = {
    79	    companyName: customer.companyName,
    80	    contactName: customer.contactName,
