     6	  DELETE_SUCCESS_MESSAGE,
     7	  EMAIL_FORMAT_ERROR,
     8	  SAVE_FAILURE_REASON,
     9	  SAVE_SUCCESS_MESSAGE,
    10	  statusColor,
    11	  type CustomerFormValues,
    12	} from "./customerModel";
    13	import { CustomerFormDrawer } from "./CustomerFormDrawer";
    14	import { useScreenState } from "./screenState";
    15	
    16	export function CustomerDetailPage() {
    17	  const { customerId = "" } = useParams();
    18	  const screenState = useScreenState();
    19	  const navigate = useNavigate();
    20	  const stored = getCustomerDetail(customerId);
    21	  const [saved, setSaved] = useState<CustomerDetail | undefined>(undefined);
    22	  const [isEditOpen, setIsEditOpen] = useState(
    23	    screenState === "drawer-open" ||
    24	      screenState === "invalid-email" ||
    25	      screenState === "loading" ||
    26	      screenState === "failure",
    27	  );
    28	  const [isDeleteOpen, setIsDeleteOpen] = useState(screenState === "delete-confirm");
    29	  const [isSaving, setIsSaving] = useState(screenState === "loading");
    30	  const [isDeleting, setIsDeleting] = useState(false);
    31	  const [saveFailureReason, setSaveFailureReason] = useState(
    32	    screenState === "failure" ? SAVE_FAILURE_REASON : "",
    33	  );
    34	  const [deleteFailureReason, setDeleteFailureReason] = useState("");
    35	  const notifiedRef = useRef(false);
    36	
    37	  useEffect(() => {
    38	    if (screenState !== "success" || notifiedRef.current) return;
    39	    notifiedRef.current = true;
    40	    toast.success(SAVE_SUCCESS_MESSAGE, { description: "顧客情報に反映しました。" });
    41	  }, [screenState]);
    42	
    43	  if (!stored) return <Navigate replace to="/customers" />;
    44	  const customer = saved && saved.id === customerId ? saved : stored;
    45	
    46	  function handleSave(values: CustomerFormValues) {
    47	    setIsSaving(true);
    48	    setSaveFailureReason("");
    49	    window.setTimeout(() => {
    50	      setIsSaving(false);
    51	      if (screenState === "failure") {
    52	        setSaveFailureReason(SAVE_FAILURE_REASON);
    53	        return;
    54	      }
    55	      setSaved({ ...customer, ...values });
    56	      setIsEditOpen(false);
    57	      toast.success(SAVE_SUCCESS_MESSAGE, { description: "顧客情報に反映しました。" });
    58	    }, 200);
    59	  }
    60	
    61	  function handleDelete() {
    62	    if (isDeleting) return;
    63	    setIsDeleting(true);
    64	    setDeleteFailureReason("");
    65	    window.setTimeout(() => {
    66	      const result = deleteCustomer(customer.id, { simulateFailure: screenState === "failure" });
    67	      setIsDeleting(false);
    68	      if (!result.ok) {
    69	        setDeleteFailureReason(result.reason);
    70	        return;
    71	      }
    72	      setIsDeleteOpen(false);
    73	      toast.success(DELETE_SUCCESS_MESSAGE, { description: `${customer.companyName}を一覧から削除しました。` });
    74	      void navigate("/customers");
    75	    }, 200);
    76	  }
    77	
    78	  const editValues: CustomerFormValues = {
    79	    companyName: customer.companyName,
    80	    contactName: customer.contactName,
    81	    email: screenState === "invalid-email" ? "aoi.sato" : customer.email,
    82	    status: customer.status,
    83	  };
    84	
    85	  return (
    86	    <main className="page-shell page-shell--stack">
    87	      <div className="detail-page__heading">
    88	        <Link className="link" to="/customers">
    89	          顧客一覧へ戻る
    90	        </Link>
    91	        <div className="page-heading">
    92	          <div className="page-heading__copy">
    93	            <h1>{customer.companyName}</h1>
    94	            <div className="page-heading__status">
    95	              <Chip color={statusColor(customer.status)} variant="soft">
    96	                {customer.status}
    97	              </Chip>
    98	            </div>
    99	          </div>
   100	          <div className="page-heading__action detail-actions">
   101	            <CustomerFormDrawer
   102	              triggerLabel="顧客を編集"
   103	              triggerVariantClass="button button--md button--primary detail-actions__item"
   104	              heading="顧客の編集"
   105	              description="登録済みの顧客情報を変更します。"
   106	              initialValues={editValues}
   107	              initialErrors={screenState === "invalid-email" ? { email: EMAIL_FORMAT_ERROR } : undefined}
   108	              isOpen={isEditOpen}
   109	              onOpenChange={setIsEditOpen}
   110	              isSaving={isSaving}
   111	              failureReason={saveFailureReason}
   112	              onSubmit={handleSave}
   113	            />
   114	            <AlertDialog isOpen={isDeleteOpen} onOpenChange={setIsDeleteOpen}>
   115	              <AlertDialog.Trigger className="detail-actions__item">
   116	                <Button variant="danger-soft" isDisabled={isDeleting}>
   117	                  顧客を削除
   118	                </Button>
   119	              </AlertDialog.Trigger>
   120	              <AlertDialog.Backdrop variant="blur">
   121	                <AlertDialog.Container placement="center">
   122	                  <AlertDialog.Dialog>
   123	                    <AlertDialog.Header>
   124	                      <AlertDialog.Icon status="danger" />
   125	                      <AlertDialog.Heading>顧客の削除</AlertDialog.Heading>
   126	                    </AlertDialog.Header>
   127	                    <AlertDialog.Body>
   128	                      <div className="dialog-body">
   129	                        <p>
   130	                          <strong>{customer.companyName}</strong>を削除します。
   131	                        </p>
   132	                        <p>削除すると基本情報と対応メモがなくなり、この操作は取り消せません。</p>
   133	                        {deleteFailureReason ? (
   134	                          <Alert status="danger">
   135	                            <Alert.Indicator />
   136	                            <Alert.Content>
   137	                              <Alert.Title>削除できませんでした</Alert.Title>
   138	                              <Alert.Description>{deleteFailureReason}</Alert.Description>
   139	                            </Alert.Content>
   140	                          </Alert>
   141	                        ) : null}
   142	                      </div>
   143	                    </AlertDialog.Body>
   144	                    <AlertDialog.Footer>
   145	                      <Button variant="tertiary" isDisabled={isDeleting} onPress={() => setIsDeleteOpen(false)}>
   146	                        キャンセル
   147	                      </Button>
   148	                      <Button variant="danger" isPending={isDeleting} isDisabled={isDeleting} onPress={handleDelete}>
   149	                        削除する
   150	                      </Button>
   151	                    </AlertDialog.Footer>
   152	                  </AlertDialog.Dialog>
   153	                </AlertDialog.Container>
   154	              </AlertDialog.Backdrop>
   155	            </AlertDialog>
   156	          </div>
   157	        </div>
   158	      </div>
   159	
   160	      <div className="detail-grid">
   161	        <Card>
   162	          <Card.Header>
   163	            <Card.Title>基本情報</Card.Title>
   164	          </Card.Header>
   165	          <Card.Content>
   166	            <dl className="detail-content">
   167	              <DetailItem label="会社名" value={customer.companyName} />
   168	              <DetailItem label="担当者名" value={customer.contactName} />
   169	              <DetailItem label="メールアドレス" value={customer.email} />
   170	              <DetailItem label="電話番号" value={customer.phone} />
   171	              <DetailItem label="ステータス" value={customer.status} />
   172	            </dl>
   173	          </Card.Content>
   174	        </Card>
   175	        <Card>
   176	          <Card.Header>
   177	            <Card.Title>対応状況</Card.Title>
   178	          </Card.Header>
   179	          <Card.Content>
   180	            <p className="detail-note">{customer.note}</p>
   181	          </Card.Content>
   182	        </Card>
   183	      </div>
   184	    </main>
   185	  );
   186	}
   187	
   188	function DetailItem({ label, value }: { label: string; value: string }) {
   189	  return (
   190	    <div className="detail-item">
   191	      <dt className="detail-item__label">{label}</dt>
   192	      <dd className="detail-item__value">{value}</dd>
   193	    </div>
   194	  );
   195	}

