/** example.account-management の componentUsage["component.table"].columns をそのまま持つ定義 */
type CustomerColumn = {
  id: "companyName" | "contactName" | "lastContactedAt" | "status";
  label: string;
  width: string;
  minWidth: number;
  align: "start" | "end";
  isRowHeader?: boolean;
  tabular?: boolean;
